function route(req){
  const intent = classifyIntent(req.text);
  const policy = pickPolicy({ intent, tokens: countTokens(req.text), latencySLO: req.latencySLO, budget: req.budget });
  if(!safety.allow(req.text)) return refuse('Unsafe input');
  switch(intent){
    case 'search': return ragAnswer(req.text, policy);
    case 'extract': return extractJSON(req.text, policy);
    case 'tool': return callTool(req.text, policy.toolName);
    default: return generate(req.text, policy.model);
  }
}
